-- 009_ward_hierarchy.sql
-- Adds GBA hierarchy columns to the wards table and backfills from gba_wards_2025.geojson.
-- Generated from scripts/generate_009_backfill.py (see that script for source citations).
--
-- Columns added (D-21, D-41, D-43, D-44):
--   zone_name                TEXT  -- Engineering zone (10 GBA zones, 2 per corporation)
--   ro_division              TEXT  -- Revenue Officer division (used as EE-level label per D-46)
--   aro_sub_division         TEXT  -- ARO sub-division (used as AEE-level label per D-46)
--   assembly_constituency    TEXT  -- AC name
--   assembly_constituency_no INT   -- AC number (150-177 for GBA)
--   parliamentary_constituency TEXT -- Lok Sabha constituency (Delimitation Commission mapping, D-41)
--   mla_name                 TEXT  -- Elected MLA (Karnataka 2023 election, D-43)
--   mp_name                  TEXT  -- Elected MP (Lok Sabha 2024 election, D-44)
--
-- All columns are nullable (NOT NULL intentionally omitted -- new ward rows added later
-- may legitimately have NULL values until the next data refresh cycle, per D-43, D-44).

-- -- Add hierarchy columns --------------------------------------------------

ALTER TABLE wards
  ADD COLUMN zone_name                 TEXT,
  ADD COLUMN ro_division               TEXT,
  ADD COLUMN aro_sub_division          TEXT,
  ADD COLUMN assembly_constituency     TEXT,
  ADD COLUMN assembly_constituency_no  INT,
  ADD COLUMN parliamentary_constituency TEXT,
  ADD COLUMN mla_name                  TEXT,
  ADD COLUMN mp_name                   TEXT;

-- -- Backfill 369 ward rows from gba_wards_2025.geojson -----------------------
-- One UPDATE per ward row, keyed on (ward_number, ward_name) which is unique
-- across all 369 rows (verified: SELECT COUNT(DISTINCT (ward_number, ward_name))
-- FROM wards = 369 on a fresh docker-compose db after migration 004 applies).

